/// Lays words on lines that fit a width, for the windows that show a message or a description.
public enum TextWrap {
    /// The lines a text takes at a font size within a width: words are laid on a line until the next
    /// one wouldn't fit, and a word wider than the width has a line of its own. It measures with the
    /// window's font, so call it when the text changes, not every frame.
    public static func lines(_ text: String, _ fontSize: Int, _ width: Int) -> [String] {
        var lines = [String]()
        var line = ""
        for word in text.split(separator: " ").map(String.init) {
            let longer = line.count == 0 ? word : "\(line) \(word)"
            if line.count > 0, MeasureText(longer, fontSize) > width {
                lines.append(line)
                line = word
            } else {
                line = longer
            }
        }
        if line.count > 0 {
            lines.append(line)
        }
        return lines
    }
}
